#include <array>
#include <cstddef>
#include <cstdint>
extern "C" std::int64_t bitmask_assignment_count(const std::int64_t*in,std::size_t len){constexpr int P=8,T=12;if(!in||len<2||len>106||in[0]<0||in[0]>P||in[1]<0||in[1]>T)return -1;int people=static_cast<int>(in[0]),tasks=static_cast<int>(in[1]);std::array<std::array<int,P>,T+1>freq{};std::size_t pos=2;for(int p=0;p<people;++p){if(pos>=len)return -1;auto count=in[pos++];if(count<0||count>T||pos+static_cast<std::size_t>(count)>len)return -1;for(int j=0;j<count;++j){auto task=in[pos++];if(task<1||task>tasks)return -1;++freq[static_cast<int>(task)][p];}}if(pos!=len)return -1;int states=1<<people,full=states-1;std::array<std::array<std::int64_t,T+2>,1<<P>dp{};for(int mask=0;mask<states;++mask)dp[mask][tasks+1]=mask==full?1:0;for(int task=tasks;task>=1;--task)for(int mask=0;mask<states;++mask){auto ways=dp[mask][task+1];for(int p=0;p<people;++p)if(freq[task][p]&&(mask&(1<<p))==0)ways+=static_cast<std::int64_t>(freq[task][p])*dp[mask|(1<<p)][task+1];dp[mask][task]=ways;}return dp[0][1];}
